857	// bi is recovered from work where needed (page_table indexing); keep it out of PfTile to save a reg.
858	__device__ __forceinline__ int pf_bi(int work, int tiles_m, int hkv) { return work / (tiles_m * hkv); }
859	
860	// Split-KV: an empty/masked/padded CTA (no key tiles to process) must still stamp -inf into its
861	// LSEpart rows so combine_kernel drops it. Doing it here lets LSEpart be a plain at::empty -- it
862	// replaces a per-call host-side at::full that memset the WHOLE scratch (an extra ~2us fill kernel +
863	// launch every decode call) even though the typical split has no empties. Only the consumer
864	// warpgroups carry rows; the (cwg/warp/group, tg==0) -> (qidx,qhead) mapping mirrors the epilogue.
865	__device__ __forceinline__ void emit_empty_lse(float* __restrict__ LSEpart, int tid, int split, int hq,
866	        int row0, int Mrows, int hk, int rep, int q0, int total_q) {
867	    if (tid < WG) return;                              // producer warpgroup carries no rows
868	    const int cwg = tid / WG - 1, wt = tid % WG, wp = wt >> 5, ln = wt & 31;
869	    if ((ln & 3) != 0) return;                         // only tg==0 writes the LSE (matches epilogue)
870	#pragma unroll
871	    for (int r = 0; r < 2; ++r) {
872	        const int idx = row0 + cwg * 64 + wp * 16 + (ln >> 2) + (r ? 8 : 0);
873	        if (idx < Mrows)
874	            LSEpart[((long)split * hq + hk * rep + idx % rep) * total_q + q0 + idx / rep] = -INFINITY;
875	    }
876	}
877	
878	// Single-split (num_splits==1) analogue of emit_empty_lse for a fully-masked / empty / padded tile:
879	// write 0 to O and -inf to LSE for the tile's valid rows. Without this a fully-masked m-tile (causal
880	// q>>k: every row's qabs < 0 -> n_max==0 -> empty_cta) would `return` before the mainloop, leaving its
881	// O rows at the uninitialized at::empty value (garbage). FA3 returns 0 for such rows. The
882	// (cwg/warp/group, tg) -> (qidx,qhead,dv) mapping mirrors the epilogue exactly.
883	template <typename TC, int HDV>
884	__device__ __forceinline__ void emit_zero_o(TC* __restrict__ O, float* __restrict__ LSE, int tid,
885	        int row0, int Mrows, int hk, int rep, int q0, int total_q, long o_row, long o_head) {
886	    if (tid < WG) return;                              // producer warpgroup carries no rows
887	    const int cwg = tid / WG - 1, wt = tid % WG, wp = wt >> 5, ln = wt & 31;
888	    const int group = ln >> 2, tg = ln & 3;
889	    const int row_lo = cwg * 64 + wp * 16 + group, row_hi = row_lo + 8;
890	    const uint32_t z = pack_2x<TC>(0.f, 0.f);
891	#pragma unroll
892	    for (int r = 0; r < 2; ++r) {
893	        const int idx = row0 + (r == 0 ? row_lo : row_hi);
894	        if (idx >= Mrows) continue;
895	        const int token = idx / rep, qhead = hk * rep + idx % rep, qidx = q0 + token;
896	        const long obase = (long)qidx * o_row + (long)qhead * o_head;
897	#pragma unroll
898	        for (int c = 0; c < HDV / 8; ++c) *reinterpret_cast<uint32_t*>(&O[obase + 8 * c + 2 * tg]) = z;
899	        if (tg == 0) LSE[(long)qhead * total_q + qidx] = -INFINITY;
900	    }
901	}
