1283	// ===================== persistent continuous-ring prefill (hd128 bf16 TMA) =====================
1284	// FA3-style persistent kernel: each CTA grabs work-items off a static stride (work = blockIdx.x +
1285	// k*gridDim.x) and processes them in a loop. The win vs the per-tile prefill_kernel is that the K/V
1286	// ring is ONE CONTINUOUS stream across work-items -- PipelineState (the ring index g + its phase) is
1287	// declared once and NEVER reset per item, so the producer prefetches the next item's K/V into slots
1288	// the consumer just freed, with no per-item pipeline-fill bubble. (The earlier naive per-item-reinit
1289	// persistent attempt regressed precisely because it paid that fill + barrier-reinit cost every item.)
1290	//
1291	// Q is single-buffered with a barQf/barQe ping-pong (phase = witer&1): the producer waits barQe (the
1292	// consumer freed the prior Q), reloads Q -- via ONE async TMA box-set (rep==1, mapQ) so the reload is
1293	// cheap enough to hide behind the continuous ring; GQA/paged would fall back to the cp.async gather --
1294	// then signals barQf. To keep the ring primed across the boundary the producer issues the item's FIRST
1295	// K/V tile (empty-gated on the global g, NOT Q-gated) BEFORE the barQe wait, then floods the rest after
1296	// Q. Stage index / phase everywhere use the GLOBAL counter g so
1297	// producer and consumer stay in lock-step (both advance g by n_cnt per non-empty item, skip empties
1298	// identically). num_splits is implicitly 1 (prefill); no split-KV epilogue. TMA-only (routed so).
1299	template <typename TIn, typename TC, int HD, int HDV, bool USE_TMA, bool EXTRA, int STAGES, int CN = CTA_N,
1300	          int CM = CTA_M, int MINB = 1>
1301	__global__ __launch_bounds__(WG * (1 + CM / 64), MINB) void prefill_persist_kernel(
1302	        const TIn* __restrict__ Q, const TIn* __restrict__ K,
1303	        const TIn* __restrict__ V, TC* __restrict__ O, float* __restrict__ LSE,
1304	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
1305	        const int* __restrict__ page_table,
1306	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head, long o_row, long o_head,
1307	        int hkv, int rep, int total_q, int block_size, int page_stride,
1308	        float scale, int causal, float softcap, int win_l, int win_r,
1309	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
1310	        const float* __restrict__ v_descale, int ds_b, int ds_h,
1311	        int tiles_m, int batch, int* __restrict__ work_ctr, const float* __restrict__ s_aux,
1312	        const __grid_constant__ CUtensorMap mapK, const __grid_constant__ CUtensorMap mapV,
1313	        const __grid_constant__ CUtensorMap mapQ) {
1314	    constexpr int HDsm  = ((HD  + 63) / 64) * 64;
1315	    constexpr int HDVsm = ((HDV + 63) / 64) * 64;
1316	    constexpr int KSTRIDE = CN * HDsm;
1317	    constexpr int VSTRIDE = CN * HDVsm;
1318	    constexpr int NCONS = (CM / 64) * WG;
1319	
1320	    constexpr int QBUF = 1;                    // Single Q buffer: rep==1 Q is reloaded via ONE async TMA
1321	                                               // (mapQ), fast enough that the STAGES-deep continuous K/V
1322	                                               // ring hides it across the item boundary. Double-Q hid the
1323	                                               // reload too but forced STAGES=2 (smem) -> starved K/V.
1324	    constexpr int SDEPTH = 2;                  // dynamic-scheduler work FIFO depth (producer lookahead)
1325	    TC* sQ = reinterpret_cast<TC*>(pf_smem);
1326	    TC* sK0 = sQ + QBUF * CM * HDsm;
1327	    TC* sV0 = sK0 + STAGES * KSTRIDE;
1328	    uint64_t* bars = reinterpret_cast<uint64_t*>(sV0 + STAGES * VSTRIDE);
1329	    uint64_t* full = bars;                     // [STAGES] count 1 (TMA tx-barrier)
1330	    uint64_t* empty = bars + STAGES;           // [STAGES] count NCONS
1331	    uint64_t* barQf = bars + 2 * STAGES;       // [QBUF] Q ready (producer -> consumers), count NumProd
1332	    uint64_t* barQe = bars + 2 * STAGES + QBUF;// [QBUF] Q free  (consumers -> producer), count NCONS
1333	    uint64_t* schF = bars + 2 * STAGES + 2 * QBUF;          // [SDEPTH] work ready (producer -> consumers)
1334	    uint64_t* schE = bars + 2 * STAGES + 2 * QBUF + SDEPTH; // [SDEPTH] slot free (consumers -> producer)
1335	    int* schW = reinterpret_cast<int*>(bars + 2 * STAGES + 2 * QBUF + 2 * SDEPTH);  // [SDEPTH] grabbed work idx
1336	
1337	    // Q via single async TMA when KV is contiguous (non-paged): rep==1 uses one 2D [CM,64] box per
1338	    // col-block; packed-GQA (rep>1, rep|CM) uses one 3D [64,rep,CM/rep] box per col-block (mapQ is built
1339	    // accordingly by the launcher). Both land in the same swizzled tile gather_row_k would have built, so
1340	    // the per-item Q reload is one async TMA (not a 128-row cp.async gather) -- which is what makes the
1341	    // persistent ring WIN for GQA/MQA (the gather reload serialized and lost to the per-tile grid).
1342	    // Paged / rep-not-dividing-CM keep the cp.async gather.
1343	    const bool tmaq     = USE_TMA && (page_table == nullptr) && (rep == 1);
1344	    const bool tmaq_gqa = USE_TMA && (page_table == nullptr) && (rep > 1) && (CM % rep == 0);
1345	    const int tid = threadIdx.x;
1346	    if (tid == 0) {
1347	#pragma unroll
1348	        for (int s = 0; s < STAGES; ++s) { mbar_init(&full[s], USE_TMA ? 1 : NumProd); mbar_init(&empty[s], NCONS); }
1349	#pragma unroll
1350	        for (int s = 0; s < QBUF; ++s) { mbar_init(&barQf[s], (tmaq || tmaq_gqa) ? 1 : NumProd); mbar_init(&barQe[s], NCONS); }
1351	#pragma unroll
1352	        for (int s = 0; s < SDEPTH; ++s) { mbar_init(&schF[s], 1); mbar_init(&schE[s], NCONS); }
1353	    }
1354	    __syncthreads();
1355	
1356	    // Dynamic LPT-free balancing: instead of static work=blockIdx.x+k*gridDim.x (which strands the
1357	    // causal triangular load -- early m-tiles are light, late ones heavy -- on fixed CTAs), each CTA
1358	    // pulls the next tile from a global atomic counter. The producer's lead thread grabs + publishes the
1359	    // index through a tiny smem FIFO (schW/schF/schE) so both warpgroups process the SAME stream while
1360	    // the GPU load-balances across CTAs the way the HW block scheduler does for the per-tile grid.
1361	    const int total_work = tiles_m * hkv * batch;
1362	    const int wg = tid / WG;
1363	
1364	    if (wg == 0) {
1365	        // ---------- producer ----------
1366	        producer_regs();
1367	        const int pt = tid;
1368	        constexpr int KBOX = HD / 64, VBOX = HDV / 64, CB = CN * 64;
1369	        const bool np = (page_table == nullptr);                      // non-paged contiguous KV
1370	        const int pages = np ? 0 : (CN / block_size);
1371	        const uint32_t kv_bytes = (uint32_t)((CN * HD + CN * HDV) * sizeof(TC));
1372	        int g = 0, witer = 0;
1373	        for (int it = 0; ; ++it) {
1374	            // Pull the next tile from the global atomic; pt==0 grabs + publishes via schW, the producer
1375	            // warpgroup broadcasts it (bar.sync), and pt==0 signals schF for the consumers.
1376	            const int sslot = it % SDEPTH;
1377	            if (pt == 0 && it >= SDEPTH) { int ep = ((it / SDEPTH) - 1) & 1; while (!mbar_try_wait(&schE[sslot], ep)) {} }
1378	            if (pt == 0) schW[sslot] = atomicAdd(work_ctr, 1);
1379	            asm volatile("bar.sync 1, %0;\n" :: "r"(WG) : "memory");
1380	            const int work = schW[sslot];
1381	            if (pt == 0) { __threadfence_block(); mbar_arrive(&schF[sslot]); }
1382	            if (work >= total_work) break;
1383	            PfTile t = pf_work<CN, CM, EXTRA>(work, tiles_m, hkv, rep, cu_q, cu_k, seqused_k,
1384	                                              causal, win_l, win_r, scale, q_descale, k_descale, v_descale, ds_b, ds_h);
1385	            if (!t.valid) continue;
1386	            const int gbase = g;
1387	            g += t.n_cnt;
1388	            const int bi = pf_bi(work, tiles_m, hkv);
1389	            const int last_pg = np ? 0 : ((t.seqlen_k - 1) / block_size);
1390	            const int ybase = np ? (cu_k ? cu_k[bi] : 0) : 0;         // non-paged: absolute key row of req bi
1391	            const int xk = t.hk * HD, xv = t.hk * HDV;
1392	            // load absolute key-tile nb into ring stage (gg % STAGES); pt==0 issues the TMA boxes.
1393	            // empty-gate on the GLOBAL gg keeps the ring a single continuous stream across items.
1394	            auto load_kv = [&](int gg, int nb) {
1395	                const int st = gg % STAGES;
1396	                if (gg >= STAGES) { int ep = ((gg / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1397	                TC* sKp = sK0 + st * KSTRIDE;
1398	                TC* sVp = sV0 + st * VSTRIDE;
1399	                mbar_expect_tx(&full[st], kv_bytes);
1400	                if (np) {
1401	                    // contiguous (non-paged): ONE [CN,64] box per col-block (same swizzled layout as paged).
1402	                    const int yk = ybase + nb * CN;
1403	#pragma unroll
1404	                    for (int bx = 0; bx < KBOX; ++bx) tma_box(sKp + bx * CB, &mapK, xk + bx * 64, yk, &full[st]);
1405	#pragma unroll
1406	                    for (int bx = 0; bx < VBOX; ++bx) tma_box(sVp + bx * CB, &mapV, xv + bx * 64, yk, &full[st]);
1407	                } else {
1408	                    for (int p = 0; p < pages; ++p) {
1409	                        int pg = nb * pages + p; if (pg > last_pg) pg = last_pg;
1410	                        int yrow = page_table[(long)bi * page_stride + pg] * block_size;
1411	                        int boff = p * block_size * 64;
1412	#pragma unroll
1413	                        for (int bx = 0; bx < KBOX; ++bx) tma_box(sKp + boff + bx * CB, &mapK, xk + bx * 64, yrow, &full[st]);
1414	#pragma unroll
1415	                        for (int bx = 0; bx < VBOX; ++bx) tma_box(sVp + boff + bx * CB, &mapV, xv + bx * 64, yrow, &full[st]);
1416	                    }
1417	                }
1418	            };
