1420	            if (pt == 0) load_kv(gbase, t.n_lo);
1421	            // (2) Q into buffer slot witer%QBUF: wait the consumer freed it (item witer-QBUF), reload,
1422	            //     signal. rep==1 reloads via ONE TMA box-set; GQA/paged fall back to the cp.async gather.
1423	            const int qslot = witer % QBUF;
1424	            const int qcyc = witer / QBUF;
1425	            TC* sQs = sQ + qslot * (CM * HDsm);
1426	            if (witer >= QBUF) { int p = (qcyc - 1) & 1; while (!mbar_try_wait(&barQe[qslot], p)) {} }
1427	            if (tmaq) {
1428	                if (pt == 0) {
1429	                    mbar_expect_tx(&barQf[qslot], (uint32_t)(CM * HD * (int)sizeof(TC)));
1430	                    const int yq = t.q0 + t.row0, xq = t.hk * HD;  // rep==1 -> qhead == hk
1431	                    constexpr int QBOX = HD / 64;
1432	#pragma unroll
1433	                    for (int bx = 0; bx < QBOX; ++bx) tma_box(sQs + bx * (CM * 64), &mapQ, xq + bx * 64, yq, &barQf[qslot]);
1434	                }
1435	            } else if (tmaq_gqa) {
1436	                if (pt == 0) {
1437	                    mbar_expect_tx(&barQf[qslot], (uint32_t)(CM * HD * (int)sizeof(TC)));
1438	                    // 3D box: token z = q0 + row0/rep (rep|CM => row0/rep is the tile's first token),
1439	                    // head y = hk*rep, col x = bx*64. One box per col-block fills the [CM,64] swizzle tile.
1440	                    const int zq = t.q0 + t.row0 / rep, yq = t.hk * rep;
1441	                    constexpr int QBOX = HD / 64;
1442	#pragma unroll
1443	                    for (int bx = 0; bx < QBOX; ++bx) tma_box3(sQs + bx * (CM * 64), &mapQ, bx * 64, yq, zq, &barQf[qslot]);
1444	                }
1445	            } else {
1446	                const int idx = t.row0 + pt;
1447	                const bool qval = idx < t.Mrows;
1448	                const int token = qval ? idx / rep : 0;
1449	                const int qhead = t.hk * rep + (qval ? idx % rep : 0);
