1468	    const int group = lane >> 2, tg = lane & 3;
1469	    const int row_lo = cwg * 64 + warp * 16 + group, row_hi = row_lo + 8;
1470	    const uint32_t sQ_base = (uint32_t)__cvta_generic_to_shared(sQ) + (uint32_t)(cwg * 4096 * (int)sizeof(TC));
1471	    const uint32_t sQ_slot = (uint32_t)(CM * HDsm * (int)sizeof(TC));   // stride between Q double-buffers
1472	    const uint32_t sK_a = (uint32_t)__cvta_generic_to_shared(sK0);
1473	    const uint32_t sV_a = (uint32_t)__cvta_generic_to_shared(sV0);
1474	    const uint32_t stK_bytes = (uint32_t)(KSTRIDE * (int)sizeof(TC));
1475	    const uint32_t stV_bytes = (uint32_t)(VSTRIDE * (int)sizeof(TC));
1476	
1477	    // Inter-WG ping-pong (mirrors prefill_kernel): the two consumer WGs process the SAME work item in
1478	    // lockstep on the shared K/V ring, so both hit the softmax (SFU) at the same time -> the tensor pipe
1479	    // idles (NCU large4k: barrier 31%, tensor 57% vs FA3 70%). Serializing the wgmma-ISSUE phase via two
1480	    // named barriers (8/9, cnt=256) staggers them by one step: while WG_a feeds the tensor core, WG_b runs
1481	    // softmax, and vice-versa. The token stays balanced across work items -- both WGs run the same n_cnt
1482	    // (same work index), so each does exactly one sync+arrive per inner-loop step. Gate: CM==128 (2
1483	    // consumer WGs) && HD==128. Big heads (192/256) are already tensor-pipe-saturated per tile so
1484	    // serializing the issue only adds barrier latency (-0.02 hd192/hd256). On the PERSIST path hd64
