1486	    // the extra barrier dominates) and hd96 was flat -- so unlike the per-tile kernel (HD<=128) the
1487	    // persist ping-pong is scoped to HD==128, where the win is real (local 0.89->0.96, causal 0.95->0.97,
1488	    // gqa 0.91->0.93).
1489	    // hd256: ping-pong measured NEUTRAL here (the two consumer WGs' softmax stall isn't what bounds it),
1490	    // so it stays off. hd192->dv128 (HDV=128, acc_o[64]) has more softmax relative to its smaller PV than
1491	    // hd192/hdv192, so staggering the WGs' issue overlaps it -- enabled to give that borderline config margin.
1492	    constexpr bool PINGPONG = (CM == 128) && (HD == 128 || (HD == 192 && HDV == 128));
1493	    constexpr int PP_BASE = 8, PP_CNT = 2 * WG;   // barriers 8/9, 256 threads (both consumer WGs)
1494	    if constexpr (PINGPONG) { if (cwg == 0) nb_arrive(PP_BASE, PP_CNT); }  // WG0 issues first
1495	
1496	    int g = 0, witer = 0;
1497	    for (int it = 0; ; ++it) {
1498	        // Read the producer-grabbed work index for this slot, then free the slot for reuse.
1499	        const int sslot = it % SDEPTH;
1500	        { int p = (it / SDEPTH) & 1; while (!mbar_try_wait(&schF[sslot], p)) {} }
1501	        const int work = schW[sslot];
1502	        __threadfence_block();
1503	        mbar_arrive(&schE[sslot]);
1504	        if (work >= total_work) break;
1505	        PfTile t = pf_work<CN, CM, EXTRA>(work, tiles_m, hkv, rep, cu_q, cu_k, seqused_k,
1506	                                          causal, win_l, win_r, scale, q_descale, k_descale, v_descale, ds_b, ds_h);
1507	        if (!t.valid) {                              // fully-masked / empty / padded item -> O=0, LSE=-inf
1508	            emit_zero_o<TC, HDV>(O, LSE, tid, t.row0, t.Mrows, t.hk, rep, t.q0, total_q, o_row, o_head);
1509	            continue;
1510	        }
1511	        const int gbase = g;
1512	        g += t.n_cnt;
1513	        const int qpos_lo = ((t.row0 + row_lo) / rep) + t.delta, qpos_hi = ((t.row0 + row_hi) / rep) + t.delta;
1514	
1515	        float acc_o[HDVsm / 2];
1516	#pragma unroll
1517	        for (int i = 0; i < HDVsm / 2; ++i) acc_o[i] = 0.f;
