2762	// parallelism for DRAM-latency-bound decode). Returns the deepest pipeline that fits.
2763	static constexpr int ds_fit_stages(int cn, int hdsm, int hdvsm, int cm = pf::CTA_M, int occ = 1) {
2764	    const int per = (cn * hdsm + cn * hdvsm) * 2;
2765	    const int qb  = cm * hdsm * 2;
2766	    const int budget = (227 * 1024 - 64) / occ;
2767	    int s = DS_MAX_STAGES;
2768	    while (s > 1 && qb + s * per > budget) --s;
2769	    return s;
